head.script:
scwin.screenId = "uldmgt50006";

///////// 1. 변수 및 선언 영역 /////////

scwin.voidMessage = $c.util.getComponent('voidMessage');

scwin.frame = undefined;

scwin.winWidth = 512;

scwin.winHeight = 370;

scwin.attachCount = "${fn:length(byformAttaches)}";

scwin.isExpand = false;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "img_13", attr: "src", fn: function () { return "/img/filing/body/pop_title_" + String(((String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("mode"))) === "create") ? "6" : "7")) + ".gif"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

scwin.obj = undefined; try { scwin.obj = /* sdd-asis-lifecycle:begin obj — as-is 원문 본문(전환 이관 · 포팅 적용됨) */opener.Potential.Provider/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50006' }); }

scwin.frameId = undefined; try { scwin.frameId = /* sdd-asis-lifecycle:begin frameId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.ActiveFrame.FrameID/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50006' }); }

scwin.delAttach = delAttach;

scwin.up = up;

scwin.down = down;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50006.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.form_1_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.form_1_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin form_1_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50006.form_1_onsubmit' }); }
};

/**
 * @event
 * @name scwin.ipt_formKorNm_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_formKorNm_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_formKorNm_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.onEnter()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50006.ipt_formKorNm_onkeyup' }); }
};

/**
 * @event
 * @name scwin.img_53_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_53_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_53_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50006.img_53_onclick' }); }
};

/**
 * @event
 * @name scwin.attachTable_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.attachTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_byformAttaches');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_byformAttaches'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_Up (행 동작 열이 하나라 못 실었다 — as-is 는 같은 칸에 동작 여럿) · fn_DelAttach → removeRow (as-is 의 «남은 수 0 안내»는 미이관) · fn_DelAttach (행 동작 열이 하나라 못 실었다 — as-is 는 같은 칸에 동작 여럿) */
        if (columnId === "__rowAct") { dl.moveRow(rowIndex, rowIndex + 1); return; } 
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'attachTable.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.img_97_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_97_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_97_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.insert()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50006.img_97_onclick' }); }
};

/**
 * @event
 * @name scwin.img_98_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_98_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_98_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50006.img_98_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/updateByformAttach.do",
        ref: "dma_InsertReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50006.tx_fn_Insert" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Search_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Search_xhr", unresolved: "action:self_submit:tx_fn_Search_xhr" };
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/filing/updateByformAttach.do",
        ref: "dma_loadListReq",
        target: "dlt_byformAttaches=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50006.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.attachTable_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.attachTable_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_byformAttaches');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'attachTable.fillAct' });
    }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_editForm.action = "/filing/updateByformAttach.do";
    $c.util.getComponent('dma_InsertReq').set('method', "searchFormKorNm");
    await scwin.tx_fn_Search_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('txt_formListDiv').setValue(responseText);
    if (!scwin.isExpand) {

    }
    scwin.isExpand = true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onEnter
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onEnter = async function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.search();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selectForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param _index
 * @returns
 * @hidden N
*/
scwin.selectForm = async function (_index) {
    /* sdd-asis-lifecycle:begin fn_SelectForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formCd = $c.util.getComponent("document.all.cd_" + _index).getValue().trim();
    const formVer = $c.util.getComponent("document.all.ver_" + _index).getValue().trim();
    const formKorNm = $c.util.getComponent("document.all.nm_" + _index).getValue().trim();
    if (scwin.isExit(formCd, formVer)) {
        await $c.win.alert("이미 추가된 서식입니다.");
        return;
    }
    scwin.addAttach(formCd, formVer, formKorNm);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isExit
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer
 * @returns
 * @hidden N
*/
scwin.isExit = function (formCd, formVer) {
    /* sdd-asis-lifecycle:begin isExit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (document.editForm.formCds == null) {
        return false;
    }
    if ($c.util.getComponent('dlt_byformAttaches').getTotalRow() == null) {
        return ($c.util.getComponent("dma_InsertReq").get("formCds") === formCd && $c.util.getComponent("dma_InsertReq").get("formVers") === formVer);
    }
    for (let i = 0; i < $c.util.getComponent('dlt_byformAttaches').getTotalRow(); i++) {
        if ($c.util.getComponent('dlt_byformAttaches').getCellData(i, 'formCd')=== formCd && $c.util.getComponent('dlt_byformAttaches').getCellData(i, 'formVer')=== formVer) {
            return true;
        }
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addAttach
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer formKorNm
 * @returns
 * @hidden N
*/
scwin.addAttach = function (formCd, formVer, formKorNm) {
    /* sdd-asis-lifecycle:begin fn_AddAttach — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const ptab = $c.util.getComponent('attachTable');
    const newAttach = ptab.insertRow();
    const formCell = newAttach.insertCell();
    formCell.className = "data_d";
    formCell.id = "attachForm";
    formCell.height = "20";
    formCell.innerHTML = "<input type=\"hidden\" name=\"formCds\" value=\"" + formCd + "\" />" + "<input type=\"hidden\" name=\"formVers\" value=\"" + formVer + "\" />" + formKorNm;
    const mandtryCell = newAttach.insertCell();
    mandtryCell.width = "80";
    mandtryCell.id = "attachMandtry";
    mandtryCell.innerHTML = $c.util.getComponent("dma_InsertReq").get("tempFormMandtryTpCds");
    const buttonCell = newAttach.insertCell();
    buttonCell.width = "80";
    buttonCell.className = "btn_action";
    buttonCell.innerHTML = "<img id=\"downButton\" src=\"/img/filing/body/arrow_down2.gif\" onclick=\"down(this)\"" + " style=\"cursor:hand\" align=\"absmiddle\" />" + " <img id=\"upButton\" src=\"/img/filing/body/arrow_up2.gif\" onclick=\"up(this)\"" + " style=\"cursor:hand\" align=\"absmiddle\" />" + " <img src=\"/img/filing/btn/btn_sub.gif\" onclick=\"delAttach(this)\"" + " style=\"cursor:hand\" align=\"absmiddle\" />";
    if (scwin.attachCount > 0) {

    } else {
        scwin.voidMessage.setStyle("display", "none");
    }
    scwin.attachCount++;
    /* sdd-asis-lifecycle:end */
};


function delAttach(obj) {
    /* sdd-asis-lifecycle:begin fn_DelAttach — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _tr = obj.parentNode.parentNode;
    const _tbl = _tr.parentNode;
    _tbl.removeChild(_tr);
    if (scwin.attachCount > 1) {

    } else {
        scwin.voidMessage.setStyle("display", "block");
    }
    scwin.attachCount--;
    /* sdd-asis-lifecycle:end */
}

function up(upObj) {
    /* sdd-asis-lifecycle:begin fn_Up — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let i = 0;
    if ($c.util.getComponent('upButton') != null) {
        if ($c.util.getComponent('upButton').length == null) {
            return;
        }
        for (i = 0; i < $c.util.getComponent('upButton').length; i++) {
            if (upObj === $c.util.getComponent('upButton')[i]) {
                break;
            }
        }
    }
    if (i == 0) {
        return;
    }
    let tempHtml = $c.util.getComponent('attachForm')[i].innerHTML;
    $c.util.getComponent('attachForm')[i].innerHTML = $c.util.getComponent('attachForm')[i - 1].innerHTML;
    $c.util.getComponent('attachForm')[i - 1].innerHTML = tempHtml;
    tempHtml = $c.util.getComponent('attachMandtry')[i].innerHTML;
    $c.util.getComponent('attachMandtry')[i].innerHTML = $c.util.getComponent('attachMandtry')[i - 1].innerHTML;
    $c.util.getComponent('attachMandtry')[i - 1].innerHTML = tempHtml;
    /* sdd-asis-lifecycle:end */
}

function down(downObj) {
    /* sdd-asis-lifecycle:begin fn_Down — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let i = 0;
    let rowCount = 0;
    if ($c.util.getComponent('downButton') != null) {
        if ($c.util.getComponent('downButton').length == null) {
            return;
        }
        rowCount = $c.util.getComponent('downButton').length;
        for (i = 0; i < $c.util.getComponent('downButton').length; i++) {
            if (downObj === $c.util.getComponent('downButton')[i]) {
                break;
            }
        }
    }
    if (rowCount - 1 === i) {
        return;
    }
    let tempHtml = $c.util.getComponent('attachForm')[i].innerHTML;
    $c.util.getComponent('attachForm')[i].innerHTML = $c.util.getComponent('attachForm')[i + 1].innerHTML;
    $c.util.getComponent('attachForm')[i + 1].innerHTML = tempHtml;
    tempHtml = $c.util.getComponent('attachMandtry')[i].innerHTML;
    $c.util.getComponent('attachMandtry')[i].innerHTML = $c.util.getComponent('attachMandtry')[i + 1].innerHTML;
    $c.util.getComponent('attachMandtry')[i + 1].innerHTML = tempHtml;
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.insert
